CREATE TABLE toolsathi_Dealer (
  dealerId NVARCHAR(120) NOT NULL,
  name NVARCHAR(120),
  "LANGUAGE" NVARCHAR(120),
  PRIMARY KEY(dealerId)
);

CREATE TABLE toolsathi_NcCode (
  code NVARCHAR(120) NOT NULL,
  "GROUP" NVARCHAR(120),
  description NCLOB,
  PRIMARY KEY(code)
);

CREATE TABLE toolsathi_Counter (
  name NVARCHAR(120) NOT NULL,
  value BIGINT,
  PRIMARY KEY(name)
);
